        Iterator<?>[] iterators = new Iterator[rowData.size()];
        Object[] keys = new Object[rowData.size()];
        final Map<Object, Object> rowValues = new LinkedHashMap<Object, Object>(rowData.size());

        // Ensure headers are set before processing rows
        if (headers == null) {
            if (headerMapping != null) {
                setHeadersFromMap(headerMapping, true);
            } else {
                setHeadersFromMap(rowData, true);
            }
        }

        int length = 0;
        for (Entry<K, I> rowEntry : rowData.entrySet()) {
            iterators[length] = rowEntry.getValue() == null ? null : rowEntry.getValue().iterator();
            keys[length] = rowEntry.getKey();
            rowValues.put(rowEntry.getKey(), null);
            length++;
        }

        boolean headersWritten = false;

        boolean nullsOnly;
        do {
            nullsOnly = true;
            for (int i = 0; i < length; i++) {
                Iterator<?> iterator = iterators[i];
                boolean isNull = iterator == null || !iterator.hasNext();
                nullsOnly &= isNull;
                if (isNull) {
                    rowValues.put(keys[i], null);
                } else {
                    rowValues.put(keys[i], iterator.next());
                }
            }
            if (!nullsOnly) {
                // Write headers if enabled and not written yet
                if (isHeaderWritingEnabled && !headersWritten) {
                    outputList.add(writeHeadersToString());
                    headersWritten = true;
                }

                if (outputList == null) {
                    if (useRowProcessor) {
                        processRecord(headerMapping, rowValues);
                    } else {
                        writeRow(headerMapping, rowValues);
                    }
                } else {
                    if (useRowProcessor) {
                        outputList.add(processRecordToString(headerMapping, rowValues));
                    } else {
                        outputList.add(writeRowToString(headerMapping, rowValues));
                    }
                }
                recordCount++; // Increment recordCount when a row is successfully processed
            }
        } while (!nullsOnly);
    } catch (Throwable t) {
        throw throwExceptionAndClose("Error processing input rows from map. Record count: " + recordCount, t);
    }
}
